    entries[WAXED_COPPER_GOLEM_STATUE].block = "WAXED_COPPER_GOLEM_STATUE";
    entries[WAXED_COPPER_GOLEM_STATUE].props = props_WAXED_COPPER_GOLEM_STATUE;
