    entries[WAXED_EXPOSED_COPPER_GOLEM_STATUE].id = "waxed_exposed_copper_golem_statue";
    entries[WAXED_EXPOSED_COPPER_GOLEM_STATUE].block = "WAXED_EXPOSED_COPPER_GOLEM_STATUE";
    entries[WAXED_EXPOSED_COPPER_GOLEM_STATUE].props = props_WAXED_EXPOSED_COPPER_GOLEM_STATUE;
    entries[WAXED_WEATHERED_COPPER_GOLEM_STATUE].name = "WAXED_WEATHERED_COPPER_GOLEM_STATUE";
    entries[WAXED_WEATHERED_COPPER_GOLEM_STATUE].id = "waxed_weathered_copper_golem_statue";
