    entries[WAXED_WEATHERED_COPPER_GOLEM_STATUE].props = props_WAXED_WEATHERED_COPPER_GOLEM_STATUE;
    entries[WAXED_OXIDIZED_COPPER_GOLEM_STATUE].name = "WAXED_OXIDIZED_COPPER_GOLEM_STATUE";
    entries[WAXED_OXIDIZED_COPPER_GOLEM_STATUE].id = "waxed_oxidized_copper_golem_statue";
    entries[WAXED_OXIDIZED_COPPER_GOLEM_STATUE].block = "WAXED_OXIDIZED_COPPER_GOLEM_STATUE";
    entries[WAXED_OXIDIZED_COPPER_GOLEM_STATUE].props = props_WAXED_OXIDIZED_COPPER_GOLEM_STATUE;
